function check(file) {
  const bytes = file.data;
  if (bytes.length === 0) return "400 empty";
  if (bytes.length > 1000) return "413 too large";
  const head = new TextDecoder().decode(bytes.slice(0, 5));
  if (head !== "%PDF-") return "415 not a pdf";
  return "ok";
}

const enc = (text) => new TextEncoder().encode(text);
console.log(check({ data: enc("%PDF-1.7 brief") }));
console.log(check({ data: new Uint8Array() }));
console.log(check({ data: new Uint8Array(5000) }));
console.log(check({ data: enc("<script>") }));

