const stored = new Set();
let nextId = 1;
async function save(file) {
  if (file === "broken") throw new Error("storage unavailable");
  const id = nextId++;
  stored.add(id);
  return id;
}
async function remove(id) {
  stored.delete(id);
}

async function uploadAll(files) {
  const saved = [];
  try {
    for (const file of files) saved.push(await save(file));
    return saved;
  } catch (error) {
    for (const id of saved) await remove(id);
    throw error;
  }
}

console.log(await uploadAll(["a", "b"]), [...stored]);
await uploadAll(["c", "d", "broken"]).catch((error) => console.log(error.message));
console.log([...stored]);

