const task = { coverKey: null, coverFence: 0 };

function setCover(task, key, fence) {
  if (fence <= task.coverFence) return { ok: false };
  const oldKey = task.coverKey;
  task.coverKey = key;
  task.coverFence = fence;
  return { ok: true, oldKey };
}

console.log(setCover(task, "cover-a", 1));
console.log(setCover(task, "cover-c", 3));
console.log(setCover(task, "cover-b", 2));
